#!/bin/bash
sed -i '/fun shareReport/,/context.startActivity(shareIntent)/c\    fun shareReport() {\n        coroutineScope.launch {\n            try {\n                val bitmap = graphicsLayer.toImageBitmap().asAndroidBitmap()\n                val cachePath = File(context.cacheDir, "images")\n                cachePath.mkdirs()\n                val file = File(cachePath, "$batchId.png")\n                val stream = FileOutputStream(file)\n                bitmap.compress(Bitmap.CompressFormat.PNG, 100, stream)\n                stream.close()\n                val uri = FileProvider.getUriForFile(context, "${context.packageName}.fileprovider", file)\n                val intent = Intent(Intent.ACTION_SEND).apply {\n                    type = "image/png"\n                    putExtra(Intent.EXTRA_STREAM, uri)\n                    addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)\n                }\n                context.startActivity(Intent.createChooser(intent, "Share Report"))\n            } catch (e: Exception) {\n                Toast.makeText(context, "Error sharing report: ${e.message}", Toast.LENGTH_SHORT).show()\n            }\n        }\n    }' app/src/main/java/com/example/ui/screens/ReportScreen.kt
